int quadratic_steps(int n) {
    int steps = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) steps++;
    }
    return steps;
}

int main() {
    printf("n=10 linear=%d quadratic=%d\n", linear_steps(10), quadratic_steps(10));
    printf("n=100 linear=%d quadratic=%d\n", linear_steps(100), quadratic_steps(100));
    return 0;
}

int halve_steps(int n) {
    int steps = 0;
    while (n > 1) {
        n = n / 2;
        steps++;
    }
    return steps;
}

int main() {
    printf("8 -> %d\n", halve_steps(8));
    printf("1024 -> %d\n", halve_steps(1024));
    printf("1000000 -> %d\n", halve_steps(1000000));
    return 0;
}

