typedef struct {
    int id;
    int score;
} Student;

int find_by_id(Student s[], int n, int id) {
    for (int i = 0; i < n; i++) {
        if (s[i].id == id) return i;
    }
    return -1;
}

int top_index(Student s[], int n) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (s[i].score > s[best].score) best = i;
    }
    return best;
}

int main() {
    Student s[3] = {{101, 88}, {102, 95}, {103, 70}};
    int k = find_by_id(s, 3, 102);
    int t = top_index(s, 3);
    printf("found=%d top=%d\n", k, t);
    return 0;
}

