exercise.solution:
typedef struct {
    int id;
    int score;
} Student;

int report(Student s[], int n, int *total, int *pass) {
    *total = 0;
    *pass = 0;
    if (n <= 0) return 0;
    for (int i = 0; i < n; i++) {
        *total += s[i].score;
        if (s[i].score >= 60) (*pass)++;
    }
    return *total / n;
}
